const zlib=require('zlib'),fs=require('fs'),path=require('path');
for(const d of fs.readdirSync('.')){
  const f=path.join(d,'session.v4.jsonl.zstd');
  if(!fs.existsSync(f))continue;
  let txt;
  try{txt=zlib.zstdDecompressSync(fs.readFileSync(f)).toString('utf8');}catch(e){console.log(d,'ERR',e.message);continue;}
  const hits=[...txt.matchAll(/restart-dsh\.ps1|restart-selfcheck|Start-ScheduledTask|Enable-ScheduledTask/g)];
