const zlib=require('zlib'),fs=require('fs'),path=require('path');
const dirs=fs.readdirSync('.');
let n=0;
for(const w of dirs){
  let subs=[];try{subs=fs.readdirSync(w)}catch(e){continue;}
  for(const d of subs){
    const f=path.join(w,d,'session.v4.jsonl.zstd');
    if(!fs.existsSync(f))continue;
    const st=fs.statSync(f);
    if(st.mtimeMs < Date.parse('2026-11-16T10:30:00+08:00')) continue;
    let txt='';try{txt=zlib.zstdDecompressSync(fs.readFileSync(f)).toString('utf8')}catch(e){continue}
    n++;
    if(/restart-dsh\.ps1/.test(txt)){
      const i=txt.search(/restart-dsh\.ps1/);
      console.log('HIT '+w+' / '+d);
      console.log(txt.slice(Math.max(0,i-400),i+200).replace(/\n/g,' | ').slice(0,700));
    }
  }
}
console.log('scanned files:',n);
